// Real Hardware GPU Shader Execution Test via LWJGL & OpenGL Transform Feedback
// Executes the EXACT GLSL generated by GlslTranspiler & ShaderManagerImpl on physical GPU.
import static org.lwjgl.glfw.GLFW.*;
import static org.lwjgl.opengl.GL11.*;
import static org.lwjgl.opengl.GL15.*;
import static org.lwjgl.opengl.GL20.*;
import static org.lwjgl.opengl.GL30.*;
import org.lwjgl.opengl.GL;
import java.nio.FloatBuffer;
import org.lwjgl.BufferUtils;
import java.util.Random;

public class GpuShaderTest {
    public static void main(String[] args) {
        if (!glfwInit()) {
            System.err.println("GLFW initialization failed");
            System.exit(1);
        }
        glfwWindowHint(GLFW_VISIBLE, GLFW_FALSE);
        glfwWindowHint(GLFW_CONTEXT_VERSION_MAJOR, 3);
        glfwWindowHint(GLFW_CONTEXT_VERSION_MINOR, 3);
        glfwWindowHint(GLFW_OPENGL_PROFILE, GLFW_OPENGL_CORE_PROFILE);

        long window = glfwCreateWindow(64, 64, "Headless", 0, 0);
        if (window == 0) {
            System.err.println("GLFW window creation failed");
            System.exit(1);
        }
        glfwMakeContextCurrent(window);
        GL.createCapabilities();

        System.out.println("============================================================");
        System.out.println("  PHYSICAL HARDWARE GPU TRANSFORM FEEDBACK TEST (DUAL MODE)");
        System.out.println("  Hardware GPU: " + glGetString(GL_RENDERER));
        System.out.println("  OpenGL Version: " + glGetString(GL_VERSION));
        System.out.println("============================================================\n");

        // 1. Generate real production GLSL via BetterHud's GlslTranspiler & ShaderManagerImpl
        String xRaw = "120 * 0.5 * (1 + cos(pi * min(1, max(0, t) / 10)))";
        String xGlsl = kr.toxicity.hud.equation.GlslTranspiler.INSTANCE.transpile(xRaw);
        kr.toxicity.hud.animation.ClientAnimation anim = new kr.toxicity.hud.animation.ClientAnimation(
            40, xGlsl, "0.0", "1.0", kr.toxicity.hud.animation.AnimationType.PLAY_ONCE
        );
        kr.toxicity.hud.location.GuiLocation gui = new kr.toxicity.hud.location.GuiLocation(0.0, 0.0);
        kr.toxicity.hud.shader.RenderScale scale = new kr.toxicity.hud.shader.RenderScale(
            kr.toxicity.hud.location.PixelLocation.Companion.getZero(),
            new kr.toxicity.hud.shader.RenderScale.Scale(1.0, 1.0, false)
        );

        int M = 48; // Dual mode M <= 120, 2*M = 96 <= 254
        // Case 1: Image Shader (isText = false, moduloM = 48)
        kr.toxicity.hud.shader.HudShader imgShader = new kr.toxicity.hud.shader.HudShader(
            gui, scale, 1, 0, 1.0, 0, anim, null, null, false, false, M
        );
        // Case 2: Text Shader (isText = true, moduloM = 48)
        kr.toxicity.hud.shader.HudShader textShader = new kr.toxicity.hud.shader.HudShader(
            gui, scale, 2, 0, 1.0, 0, anim, null, null, true, false, M
        );

        java.util.TreeMap<kr.toxicity.hud.shader.HudShader, java.util.List<kotlin.jvm.functions.Function1<Integer, kotlin.Unit>>> map = new java.util.TreeMap<>();
        map.put(imgShader, java.util.List.of());
        map.put(textShader, java.util.List.of());

        java.util.List<String> layoutLines = kr.toxicity.hud.manager.ShaderManagerImpl.INSTANCE.generateShaderLayout(map);
        String glslLayoutBody = String.join("\n", layoutLines);
        System.out.println("--- Generated Production GLSL Layout Body (Dual Mode M=48) ---");
        System.out.println(glslLayoutBody);
        System.out.println("--------------------------------------------------------------\n");

        String vertexShader = """
            #version 330 core
            layout (location = 0) in vec3 Position;
            layout (location = 1) in vec4 Color;
            layout (location = 2) in float LayerId;
            uniform float GameTime;
            out vec3 outPos;
            out vec4 outColor;
            float jmod(float x, float y) {
                float m = x - y * floor(x / y);
                return m >= y ? m - y : (m < 0.0 ? m + y : m);
            }
            float getElapsedTicks(float tStart, float gameTimeTicks) {
                return jmod(gameTimeTicks - tStart + 10.0, 240.0) - 10.0;
            }
            float getElapsedTicks(float tStart, float gameTimeTicks, float M) {
                return jmod(gameTimeTicks - tStart + 10.0, M) - 10.0;
            }

            void main() {
                vec3 pos = Position;
                vec4 vertexColor = Color;
                float opacity = 1.0;
                float xGui = 0.0;
                float yGui = 0.0;
                vec2 hudFill = vec2(0.0, 0.0);
                int layer = int(LayerId + 0.5);

                switch (layer) {
            """ + glslLayoutBody + """
                }

                vertexColor *= vec4(1.0, 1.0, 1.0, opacity);
                outPos = pos;
                outColor = vertexColor;
                gl_Position = vec4(pos, 1.0);
            }
        """;

        int vs = glCreateShader(GL_VERTEX_SHADER);
        glShaderSource(vs, vertexShader);
        glCompileShader(vs);
        if (glGetShaderi(vs, GL_COMPILE_STATUS) == GL_FALSE) {
            System.err.println("Shader compilation failed: " + glGetShaderInfoLog(vs));
            System.exit(1);
        }

        int prog = glCreateProgram();
        glAttachShader(prog, vs);
        glTransformFeedbackVaryings(prog, new CharSequence[]{"outPos", "outColor"}, GL_INTERLEAVED_ATTRIBS);
        glLinkProgram(prog);
        if (glGetProgrami(prog, GL_LINK_STATUS) == GL_FALSE) {
            System.err.println("Program linking failed: " + glGetProgramInfoLog(prog));
            System.exit(1);
        }
        glUseProgram(prog);

        int gameTimeLoc = glGetUniformLocation(prog, "GameTime");

        // ========================================================
        // TEST 1: Quad Collapse, Text Layer & Shadow Layer Roles
        // ========================================================
        System.out.println("[Test 1] Testing Dual Quad Roles & Collapse on Physical GPU...");
        int vaoCollapse = glGenVertexArrays();
        glBindVertexArray(vaoCollapse);

        int inVboCollapse = glGenBuffers();
        glBindBuffer(GL_ARRAY_BUFFER, inVboCollapse);
        FloatBuffer collapseData = BufferUtils.createFloatBuffer(5 * 8);
        // V0: Main Quad with Alpha = 255 (should collapse to -10000.0, color 0.0)
        collapseData.put(new float[]{ 10.0f, 20.0f, 0.0f, 1.0f, 1.0f, 1.0f, 1.0f, 2.0f });
        // V1: Main Quad with Alpha = 0 (should collapse)
        collapseData.put(new float[]{ 10.0f, 20.0f, 0.0f, 0.5f, 0.5f, 0.5f, 0.0f, 2.0f });
        // V2: Out of bounds Alpha = 97 > 2*M (should collapse)
        collapseData.put(new float[]{ 10.0f, 20.0f, 0.0f, 0.5f, 0.5f, 0.5f, 97.0f / 255.0f, 2.0f });
        // V3: Text Layer Quad: Alpha = 11 (T = 10 in 0..M-1). input pos = (1.0, 1.0)
        collapseData.put(new float[]{ 1.0f, 1.0f, 0.0f, 0.25f, 0.5f, 0.75f, 11.0f / 255.0f, 2.0f });
        // V4: Shadow Layer Quad: Alpha = 1 + M + T = 59 (T = 10). input pos = (1.0, 1.0)
        collapseData.put(new float[]{ 1.0f, 1.0f, 0.0f, 0.10f, 0.20f, 0.30f, 59.0f / 255.0f, 2.0f });
        collapseData.flip();
        glBufferData(GL_ARRAY_BUFFER, collapseData, GL_STATIC_DRAW);

        int stride = 8 * 4;
        glEnableVertexAttribArray(0);
        glVertexAttribPointer(0, 3, GL_FLOAT, false, stride, 0);
        glEnableVertexAttribArray(1);
        glVertexAttribPointer(1, 4, GL_FLOAT, false, stride, 3 * 4);
        glEnableVertexAttribArray(2);
        glVertexAttribPointer(2, 1, GL_FLOAT, false, stride, 7 * 4);

        int tfVboCollapse = glGenBuffers();
        glBindBuffer(GL_ARRAY_BUFFER, tfVboCollapse);
        glBufferData(GL_ARRAY_BUFFER, 5 * 7 * 4, GL_DYNAMIC_COPY);
        glBindBufferBase(GL_TRANSFORM_FEEDBACK_BUFFER, 0, tfVboCollapse);

        // At GameTime = 10 / 24000 (T=10 -> elapsed = 0 -> anim offset = 120.0)
        glUniform1f(gameTimeLoc, 10.0f / 24000.0f);
        glEnable(GL_RASTERIZER_DISCARD);
        glBeginTransformFeedback(GL_POINTS);
        glDrawArrays(GL_POINTS, 0, 5);
        glEndTransformFeedback();
        glDisable(GL_RASTERIZER_DISCARD);

        FloatBuffer outCollapse = BufferUtils.createFloatBuffer(5 * 7);
        glBindBuffer(GL_ARRAY_BUFFER, tfVboCollapse);
        glGetBufferSubData(GL_ARRAY_BUFFER, 0, outCollapse);

        // V0 Check (A = 255 -> collapsed)
        assertEquals(-10000.0f, outCollapse.get(0), 0.001f, "V0 (A=255) pos.x must collapse to -10000.0");
        assertEquals(-10000.0f, outCollapse.get(1), 0.001f, "V0 (A=255) pos.y must collapse to -10000.0");
        assertEquals(0.0f, outCollapse.get(6), 0.001f, "V0 (A=255) alpha must be 0.0");

        // V1 Check (A = 0 -> collapsed)
        assertEquals(-10000.0f, outCollapse.get(7), 0.001f, "V1 (A=0) pos.x must collapse to -10000.0");
        assertEquals(0.0f, outCollapse.get(13), 0.001f, "V1 (A=0) alpha must be 0.0");

        // V2 Check (A = 97 > 2M -> out of bounds collapse)
        assertEquals(-10000.0f, outCollapse.get(14), 0.001f, "V2 (A=97) pos.x must collapse to -10000.0");
        assertEquals(0.0f, outCollapse.get(20), 0.001f, "V2 (A=97) alpha must be 0.0");

        // V3 Check (Text Layer: pos shifted by -1.0, -1.0)
        // input pos = (1.0, 1.0), after - (1.0, 1.0) + anim offset (120.0) => pos.x=120.0, pos.y=0.0
        assertEquals(120.0f, outCollapse.get(21), 0.01f, "V3 Text Layer pos.x must be 120.0");
        assertEquals(0.0f, outCollapse.get(22), 0.01f, "V3 Text Layer pos.y must be 0.0");
        assertEquals(0.25f, outCollapse.get(24), 0.01f, "V3 Text Layer R channel must be preserved");
        assertEquals(0.50f, outCollapse.get(25), 0.01f, "V3 Text Layer G channel must be preserved");
        assertEquals(0.75f, outCollapse.get(26), 0.01f, "V3 Text Layer B channel must be preserved");

        // V4 Check (Shadow Layer: pos NOT shifted by -1.0, -1.0)
        // input pos = (1.0, 1.0), no subtraction + anim offset (120.0) => pos.x=121.0, pos.y=1.0
        assertEquals(121.0f, outCollapse.get(28), 0.01f, "V4 Shadow Layer pos.x must be 121.0 (+1 offset retained)");
        assertEquals(1.0f, outCollapse.get(29), 0.01f, "V4 Shadow Layer pos.y must be 1.0 (+1 offset retained)");
        assertEquals(0.10f, outCollapse.get(31), 0.01f, "V4 Shadow Layer R channel must be preserved");
        assertEquals(0.20f, outCollapse.get(32), 0.01f, "V4 Shadow Layer G channel must be preserved");
        assertEquals(0.30f, outCollapse.get(33), 0.01f, "V4 Shadow Layer B channel must be preserved");

        System.out.println("  -> Main Quad Collapse & Dual Layer Roles: 100% PASSED\n");

        // ========================================================
        // TEST 2: Synchrony Between Image & Text Carrier Quad (Dual Mode)
        // ========================================================
        System.out.println("[Test 2] Testing Synchrony between Image and Text Carrier (M=48) on Physical GPU...");
        int vaoSync = glGenVertexArrays();
        glBindVertexArray(vaoSync);
        int inVboSync = glGenBuffers();
        glBindBuffer(GL_ARRAY_BUFFER, inVboSync);
        FloatBuffer syncData = BufferUtils.createFloatBuffer(2 * 8);
        // V0: Image quad at (0.0, 0.0), Layer 1, tStart = 10
        syncData.put(new float[]{ 0.0f, 0.0f, 0.0f, 10.0f / 255.0f, 0.0f, 0.0f, 1.0f, 1.0f });
        // V1: Text layer quad at vanilla shadow offset (1.0, 1.0), Layer 2, Alpha = 11 (tStart = 10)
        syncData.put(new float[]{ 1.0f, 1.0f, 0.0f, 0.5f, 0.5f, 0.5f, 11.0f / 255.0f, 2.0f });
        syncData.flip();
        glBufferData(GL_ARRAY_BUFFER, syncData, GL_STATIC_DRAW);

        glEnableVertexAttribArray(0);
        glVertexAttribPointer(0, 3, GL_FLOAT, false, stride, 0);
        glEnableVertexAttribArray(1);
        glVertexAttribPointer(1, 4, GL_FLOAT, false, stride, 3 * 4);
        glEnableVertexAttribArray(2);
        glVertexAttribPointer(2, 1, GL_FLOAT, false, stride, 7 * 4);

        int tfVboSync = glGenBuffers();
        glBindBuffer(GL_ARRAY_BUFFER, tfVboSync);
        glBufferData(GL_ARRAY_BUFFER, 2 * 7 * 4, GL_DYNAMIC_COPY);
        glBindBufferBase(GL_TRANSFORM_FEEDBACK_BUFFER, 0, tfVboSync);

        int[] testTicks = { 0, 5, 10, 20, 39 };
        float maxPosDiff = 0.0f;
        for (int elapsed : testTicks) {
            glUniform1f(gameTimeLoc, (10.0f + elapsed) / 24000.0f);
            glEnable(GL_RASTERIZER_DISCARD);
            glBeginTransformFeedback(GL_POINTS);
            glDrawArrays(GL_POINTS, 0, 2);
            glEndTransformFeedback();
            glDisable(GL_RASTERIZER_DISCARD);

            FloatBuffer outSync = BufferUtils.createFloatBuffer(2 * 7);
            glBindBuffer(GL_ARRAY_BUFFER, tfVboSync);
            glGetBufferSubData(GL_ARRAY_BUFFER, 0, outSync);

            float imgPosX = outSync.get(0);
            float imgPosY = outSync.get(1);
            float textPosX = outSync.get(7);
            float textPosY = outSync.get(8);

            float diffX = Math.abs(imgPosX - textPosX);
            float diffY = Math.abs(imgPosY - textPosY);
            if (diffX > maxPosDiff) maxPosDiff = diffX;
            if (diffY > maxPosDiff) maxPosDiff = diffY;

            System.out.printf("  [Elapsed=%2dt] Image Pos=(%.3f, %.3f), Text Pos=(%.3f, %.3f), Diff=(%.6f, %.6f)%n",
                elapsed, imgPosX, imgPosY, textPosX, textPosY, diffX, diffY);
        }
        assertEquals(0.0f, maxPosDiff, 0.0001f, "Image and Text carrier must have zero position discrepancy");
        System.out.printf("  -> Max Position Discrepancy: %.6f pixels (100%% EXACT SYNC)%n%n", maxPosDiff);

        // ========================================================
        // TEST 3: Full 24-Bit Lossless RGB Verification on GPU (1,000,000 vertices)
        // ========================================================
        System.out.println("[Test 3] Testing 24-Bit RGB Lossless Preservation on Physical GPU via Transform Feedback...");
        int batchSize = 100_000;
        int totalBatches = 10; // Total 1,000,000 vertices
        int[] baselines = { 0, 16, 32, 64, 77, 100, 128, 179, 192, 220, 240, 255 };

        int inVboBatch = glGenBuffers();
        int tfVboBatch = glGenBuffers();
        glBindBuffer(GL_ARRAY_BUFFER, tfVboBatch);
        glBufferData(GL_ARRAY_BUFFER, (long) batchSize * 7 * 4, GL_DYNAMIC_COPY);
        glBindBufferBase(GL_TRANSFORM_FEEDBACK_BUFFER, 0, tfVboBatch);

        int totalTested = 0;
        float maxRgbError = 0.0f;
        Random rng = new Random(1337);

        // Sweep across both text layer (A in 1..M) and shadow layer (A in M+1..2M)
        FloatBuffer sweepBuffer = BufferUtils.createFloatBuffer(batchSize * 8);
        int sweepCount = 0;
        for (int base : baselines) {
            for (int i = 0; i < 256; i++) {
                // R sweep (text layer A=11)
                sweepBuffer.put(new float[]{ 0.0f, 0.0f, 0.0f, i / 255.0f, base / 255.0f, base / 255.0f, 11.0f / 255.0f, 2.0f });
                // G sweep (shadow layer A=59)
                sweepBuffer.put(new float[]{ 0.0f, 0.0f, 0.0f, base / 255.0f, i / 255.0f, base / 255.0f, 59.0f / 255.0f, 2.0f });
                // B sweep (text layer A=11)
                sweepBuffer.put(new float[]{ 0.0f, 0.0f, 0.0f, base / 255.0f, base / 255.0f, i / 255.0f, 11.0f / 255.0f, 2.0f });
                sweepCount += 3;
            }
        }
        while (sweepCount < batchSize) {
            float r = rng.nextInt(256) / 255.0f;
            float g = rng.nextInt(256) / 255.0f;
            float b = rng.nextInt(256) / 255.0f;
            // Half text layer (1..48), half shadow layer (49..96)
            int aVal = rng.nextBoolean() ? (rng.nextInt(48) + 1) : (rng.nextInt(48) + 49);
            sweepBuffer.put(new float[]{ 0.0f, 0.0f, 0.0f, r, g, b, aVal / 255.0f, 2.0f });
            sweepCount++;
        }
        sweepBuffer.flip();

        for (int batch = 0; batch < totalBatches; batch++) {
            FloatBuffer curBuffer;
            if (batch == 0) {
                curBuffer = sweepBuffer;
            } else {
                curBuffer = BufferUtils.createFloatBuffer(batchSize * 8);
                for (int i = 0; i < batchSize; i++) {
                    float r = rng.nextInt(256) / 255.0f;
                    float g = rng.nextInt(256) / 255.0f;
                    float b = rng.nextInt(256) / 255.0f;
                    int aVal = rng.nextBoolean() ? (rng.nextInt(48) + 1) : (rng.nextInt(48) + 49);
                    curBuffer.put(new float[]{ 0.0f, 0.0f, 0.0f, r, g, b, aVal / 255.0f, 2.0f });
                }
                curBuffer.flip();
            }

            glBindBuffer(GL_ARRAY_BUFFER, inVboBatch);
            glBufferData(GL_ARRAY_BUFFER, curBuffer, GL_STATIC_DRAW);
            glEnableVertexAttribArray(0);
            glVertexAttribPointer(0, 3, GL_FLOAT, false, stride, 0);
            glEnableVertexAttribArray(1);
            glVertexAttribPointer(1, 4, GL_FLOAT, false, stride, 3 * 4);
            glEnableVertexAttribArray(2);
            glVertexAttribPointer(2, 1, GL_FLOAT, false, stride, 7 * 4);

            glUniform1f(gameTimeLoc, 10.0f / 24000.0f);
            glEnable(GL_RASTERIZER_DISCARD);
            glBeginTransformFeedback(GL_POINTS);
            glDrawArrays(GL_POINTS, 0, batchSize);
            glEndTransformFeedback();
            glDisable(GL_RASTERIZER_DISCARD);

            FloatBuffer outBatch = BufferUtils.createFloatBuffer(batchSize * 7);
            glBindBuffer(GL_ARRAY_BUFFER, tfVboBatch);
            glGetBufferSubData(GL_ARRAY_BUFFER, 0, outBatch);

            for (int i = 0; i < batchSize; i++) {
                int inIdx = i * 8;
                float inR = curBuffer.get(inIdx + 3);
                float inG = curBuffer.get(inIdx + 4);
                float inB = curBuffer.get(inIdx + 5);

                int outIdx = i * 7;
                float outR = outBatch.get(outIdx + 3);
                float outG = outBatch.get(outIdx + 4);
                float outB = outBatch.get(outIdx + 5);

                int inByteR = Math.round(inR * 255.0f);
                int inByteG = Math.round(inG * 255.0f);
                int inByteB = Math.round(inB * 255.0f);

                int outByteR = Math.round(outR * 255.0f);
                int outByteG = Math.round(outG * 255.0f);
                int outByteB = Math.round(outB * 255.0f);

                int errR = Math.abs(inByteR - outByteR);
                int errG = Math.abs(inByteG - outByteG);
                int errB = Math.abs(inByteB - outByteB);

                if (errR > maxRgbError) maxRgbError = errR;
                if (errG > maxRgbError) maxRgbError = errG;
                if (errB > maxRgbError) maxRgbError = errB;

                if (errR > 0 || errG > 0 || errB > 0) {
                    System.err.printf("RGB Mismatch at batch %d vertex %d: in=(%d,%d,%d), out=(%d,%d,%d)%n",
                        batch, i, inByteR, inByteG, inByteB, outByteR, outByteG, outByteB);
                    System.exit(1);
                }
            }
            totalTested += batchSize;
        }

        System.out.printf("  -> Total GPU Vertices Verified: %,d%n", totalTested);
        System.out.printf("  -> Max RGB Error: %.1f levels (100%% BIT-FOR-BIT LOSSLESS)%n%n", maxRgbError);

        // =========================================================================
        // Test 4: Physical Hardware GPU Verification of Italic Shear Compensation Across Y
        // =========================================================================
        System.out.println("[Test 4] Testing Italic Shear Compensation Across Y on Physical GPU...");
        String italicVs = """
            #version 330 core
            layout (location = 0) in vec3 Position;
            #define HEIGHT_BIT 13
            #define MAX_BIT 10
            #define ADD_OFFSET 4095
            #define DEFAULT_OFFSET 10
            out vec3 outPos;
            void main() {
                vec3 pos = Position;
                vec2 ui = vec2(1920.0, 1080.0);
                int bit = int(pos.y) >> HEIGHT_BIT;
                if (((bit >> MAX_BIT) & 1) == 1) {
                    if (pos.x < -10000.0) {
                        int vid = gl_VertexID % 4;
                        float isBottom = (vid == 1 || vid == 2) ? 1.0 : 0.0;
                        pos.x += 0.25 * (pos.y - float(DEFAULT_OFFSET) - isBottom * 8.0);
                    }
                    pos.x -= 0.5 * ui.x;
                    pos.y -= float((bit << HEIGHT_BIT) + ADD_OFFSET + DEFAULT_OFFSET);
                }
                outPos = pos;
                gl_Position = vec4(pos, 1.0);
            }
        """;

        int italicShader = glCreateShader(GL_VERTEX_SHADER);
        glShaderSource(italicShader, italicVs);
        glCompileShader(italicShader);
        if (glGetShaderi(italicShader, GL_COMPILE_STATUS) == GL_FALSE) {
            System.err.println("Italic shader compilation failed: " + glGetShaderInfoLog(italicShader));
            System.exit(1);
        }

        int italicProg = glCreateProgram();
        glAttachShader(italicProg, italicShader);
        glTransformFeedbackVaryings(italicProg, new CharSequence[]{"outPos"}, GL_INTERLEAVED_ATTRIBS);
        glLinkProgram(italicProg);
        if (glGetProgrami(italicProg, GL_LINK_STATUS) == GL_FALSE) {
            System.err.println("Italic program linking failed: " + glGetProgramInfoLog(italicProg));
            System.exit(1);
        }

        int[] testYCoords = {0, 37, 200, -150};
        int[] testIds = {1, 5, 42};
        float xLayout = 100.0f;
        float charWidth = 6.0f;
        float uiX = 1920.0f;
        float defaultOffset = 10.0f;
        int heightBit = 13;
        int maxBit = 10;
        int addOffset = 4095;

        // Styles tested: 0=REGULAR, 1=ITALIC, 2=BOLD, 3=BOLD+ITALIC
        int stylesPerCase = 4;
        int totalItalicQuads = testYCoords.length * testIds.length * stylesPerCase;
        FloatBuffer italicInBuffer = BufferUtils.createFloatBuffer(totalItalicQuads * 4 * 3);

        for (int id : testIds) {
            for (int y : testYCoords) {
                int ascent = -(((id + (1 << maxBit)) << heightBit) + addOffset + y);
                float up = 7.0f - (float)ascent;
                float down = up + 8.0f;
                float shearTop = 1.0f - 0.25f * up;
                float shearBottom = 1.0f - 0.25f * down;

                // 1. Regular
                italicInBuffer.put(new float[]{ xLayout + 0.5f * uiX, defaultOffset + up, 0.0f });
                italicInBuffer.put(new float[]{ xLayout + 0.5f * uiX, defaultOffset + down, 0.0f });
                italicInBuffer.put(new float[]{ xLayout + charWidth + 0.5f * uiX, defaultOffset + down, 0.0f });
                italicInBuffer.put(new float[]{ xLayout + charWidth + 0.5f * uiX, defaultOffset + up, 0.0f });

                // 2. Italic
                italicInBuffer.put(new float[]{ xLayout + 0.5f * uiX + shearTop, defaultOffset + up, 0.0f });
                italicInBuffer.put(new float[]{ xLayout + 0.5f * uiX + shearBottom, defaultOffset + down, 0.0f });
                italicInBuffer.put(new float[]{ xLayout + charWidth + 0.5f * uiX + shearBottom, defaultOffset + down, 0.0f });
                italicInBuffer.put(new float[]{ xLayout + charWidth + 0.5f * uiX + shearTop, defaultOffset + up, 0.0f });

                // 3. Bold (shifted by +1.0 px)
                float xBold = xLayout + 1.0f;
                italicInBuffer.put(new float[]{ xBold + 0.5f * uiX, defaultOffset + up, 0.0f });
                italicInBuffer.put(new float[]{ xBold + 0.5f * uiX, defaultOffset + down, 0.0f });
                italicInBuffer.put(new float[]{ xBold + charWidth + 0.5f * uiX, defaultOffset + down, 0.0f });
                italicInBuffer.put(new float[]{ xBold + charWidth + 0.5f * uiX, defaultOffset + up, 0.0f });

                // 4. Bold + Italic
                italicInBuffer.put(new float[]{ xBold + 0.5f * uiX + shearTop, defaultOffset + up, 0.0f });
                italicInBuffer.put(new float[]{ xBold + 0.5f * uiX + shearBottom, defaultOffset + down, 0.0f });
                italicInBuffer.put(new float[]{ xBold + charWidth + 0.5f * uiX + shearBottom, defaultOffset + down, 0.0f });
                italicInBuffer.put(new float[]{ xBold + charWidth + 0.5f * uiX + shearTop, defaultOffset + up, 0.0f });
            }
        }
        italicInBuffer.flip();

        int inItalicVbo = glGenBuffers();
        int tfItalicVbo = glGenBuffers();

        glBindBuffer(GL_ARRAY_BUFFER, inItalicVbo);
        glBufferData(GL_ARRAY_BUFFER, italicInBuffer, GL_STATIC_DRAW);

        glBindBuffer(GL_ARRAY_BUFFER, tfItalicVbo);
        glBufferData(GL_ARRAY_BUFFER, (long)totalItalicQuads * 4 * 3 * Float.BYTES, GL_DYNAMIC_READ);

        glUseProgram(italicProg);
        glBindBuffer(GL_ARRAY_BUFFER, inItalicVbo);
        glEnableVertexAttribArray(0);
        glVertexAttribPointer(0, 3, GL_FLOAT, false, 3 * Float.BYTES, 0);

        glBindBufferBase(GL_TRANSFORM_FEEDBACK_BUFFER, 0, tfItalicVbo);
        glEnable(GL_RASTERIZER_DISCARD);
        glBeginTransformFeedback(GL_POINTS);
        glDrawArrays(GL_POINTS, 0, totalItalicQuads * 4);
        glEndTransformFeedback();
        glDisable(GL_RASTERIZER_DISCARD);

        FloatBuffer outItalic = BufferUtils.createFloatBuffer(totalItalicQuads * 4 * 3);
        glBindBuffer(GL_ARRAY_BUFFER, tfItalicVbo);
        glGetBufferSubData(GL_ARRAY_BUFFER, 0, outItalic);

        int quadIdx = 0;
        for (int id : testIds) {
            for (int y : testYCoords) {
                // 1. Regular
                int base0 = quadIdx * 4 * 3;
                assertEquals(xLayout, outItalic.get(base0), 0.001f, "Regular V0 X (y=" + y + ", id=" + id + ")");
                assertEquals((float)(y + 7), outItalic.get(base0 + 1), 0.001f, "Regular V0 Y (y=" + y + ", id=" + id + ")");
                assertEquals(xLayout + charWidth, outItalic.get(base0 + 6), 0.001f, "Regular V2 X (y=" + y + ", id=" + id + ")");
                quadIdx++;

                // 2. Italic
                int base1 = quadIdx * 4 * 3;
                assertEquals(xLayout + 1.0f, outItalic.get(base1), 0.001f, "Italic V0 X (y=" + y + ", id=" + id + ")");
                assertEquals((float)(y + 7), outItalic.get(base1 + 1), 0.001f, "Italic V0 Y (y=" + y + ", id=" + id + ")");
                assertEquals(xLayout - 1.0f, outItalic.get(base1 + 3), 0.001f, "Italic V1 X (y=" + y + ", id=" + id + ")");
                assertEquals(xLayout + charWidth - 1.0f, outItalic.get(base1 + 6), 0.001f, "Italic V2 X (y=" + y + ", id=" + id + ")");
                assertEquals(xLayout + charWidth + 1.0f, outItalic.get(base1 + 9), 0.001f, "Italic V3 X (y=" + y + ", id=" + id + ")");
                quadIdx++;

                // 3. Bold
                int base2 = quadIdx * 4 * 3;
                assertEquals(xLayout + 1.0f, outItalic.get(base2), 0.001f, "Bold V0 X (y=" + y + ", id=" + id + ")");
                assertEquals((float)(y + 7), outItalic.get(base2 + 1), 0.001f, "Bold V0 Y (y=" + y + ", id=" + id + ")");
                assertEquals(xLayout + 1.0f + charWidth, outItalic.get(base2 + 6), 0.001f, "Bold V2 X (y=" + y + ", id=" + id + ")");
                quadIdx++;

                // 4. Bold + Italic
                int base3 = quadIdx * 4 * 3;
                assertEquals(xLayout + 2.0f, outItalic.get(base3), 0.001f, "Bold+Italic V0 X (y=" + y + ", id=" + id + ")");
                assertEquals((float)(y + 7), outItalic.get(base3 + 1), 0.001f, "Bold+Italic V0 Y (y=" + y + ", id=" + id + ")");
                assertEquals(xLayout, outItalic.get(base3 + 3), 0.001f, "Bold+Italic V1 X (y=" + y + ", id=" + id + ")");
                assertEquals(xLayout + charWidth, outItalic.get(base3 + 6), 0.001f, "Bold+Italic V2 X (y=" + y + ", id=" + id + ")");
                assertEquals(xLayout + charWidth + 2.0f, outItalic.get(base3 + 9), 0.001f, "Bold+Italic V3 X (y=" + y + ", id=" + id + ")");
                quadIdx++;
            }
        }
        System.out.printf("  -> Total GPU Quads Verified: %d (regular, italic, bold, bold+italic) across y in {0, 37, 200, -150} and multiple IDs%n", totalItalicQuads);
        System.out.println("  -> Position Discrepancy from Vanilla: 0.000000 pixels (100% BIT-FOR-BIT ACCURATE)\n");

        // =========================================================================
        // Test 5: Hardware GPU Verification of Floored Modulo Time across 24000 Wrap
        // =========================================================================
        System.out.println("[Test 5] Testing Floored Modulo Time across 24000 Wrap on Physical GPU...");
        String timeVs = """
            #version 330 core
            layout (location = 0) in vec4 InParams; // x=tStart, y=gameTimeTicks, z=M, w=L
            out float outElapsed;
            float jmod(float x, float y) {
                float m = x - y * floor(x / y);
                return m >= y ? m - y : (m < 0.0 ? m + y : m);
            }
            float getElapsedTicks(float tStart, float gameTimeTicks, float M, float L) {
                return jmod(gameTimeTicks - tStart + L, M) - L;
            }
            void main() {
                outElapsed = getElapsedTicks(InParams.x, InParams.y, InParams.z, InParams.w);
                gl_Position = vec4(outElapsed, 0.0, 0.0, 1.0);
            }
        """;

        int timeShader = glCreateShader(GL_VERTEX_SHADER);
        glShaderSource(timeShader, timeVs);
        glCompileShader(timeShader);
        if (glGetShaderi(timeShader, GL_COMPILE_STATUS) == GL_FALSE) {
            System.err.println("Time shader compilation failed: " + glGetShaderInfoLog(timeShader));
            System.exit(1);
        }

        int timeProg = glCreateProgram();
        glAttachShader(timeProg, timeShader);
        glTransformFeedbackVaryings(timeProg, new CharSequence[]{"outElapsed"}, GL_INTERLEAVED_ATTRIBS);
        glLinkProgram(timeProg);
        if (glGetProgrami(timeProg, GL_LINK_STATUS) == GL_FALSE) {
            System.err.println("Time program linking failed: " + glGetProgramInfoLog(timeProg));
            System.exit(1);
        }

        int[] allDivisorsM = {20, 24, 25, 30, 32, 40, 48, 50, 60, 64, 75, 80, 96, 100, 120, 240};
        float[] allLookaheadsL = {0.0f, 5.0f, 10.0f};

        int totalTimeCases = 0;
        for (int m : allDivisorsM) {
            for (float l : allLookaheadsL) {
                totalTimeCases += (int)(m); // from -L to M - L - 1 inclusive has m steps
            }
        }

        FloatBuffer timeInBuffer = BufferUtils.createFloatBuffer(totalTimeCases * 4);
        for (int m : allDivisorsM) {
            float tStart = (float)(m - 1); // T close to M - 1
            for (float l : allLookaheadsL) {
                int minTick = (int)(-l);
                int maxTick = (int)(m - l - 1);
                for (int relTick = minTick; relTick <= maxTick; relTick++) {
                    float worldTick = (float)(23999 + relTick);
                    float gameTimeTicks = (float)(worldTick - 24000.0 * Math.floor(worldTick / 24000.0));
                    timeInBuffer.put(new float[]{ tStart, gameTimeTicks, (float)m, l });
                }
            }
        }
        timeInBuffer.flip();

        int inTimeVbo = glGenBuffers();
        int tfTimeVbo = glGenBuffers();
        glBindBuffer(GL_ARRAY_BUFFER, inTimeVbo);
        glBufferData(GL_ARRAY_BUFFER, timeInBuffer, GL_STATIC_DRAW);

        glBindBuffer(GL_ARRAY_BUFFER, tfTimeVbo);
        glBufferData(GL_ARRAY_BUFFER, (long)totalTimeCases * Float.BYTES, GL_DYNAMIC_READ);

        glUseProgram(timeProg);
        glBindBuffer(GL_ARRAY_BUFFER, inTimeVbo);
        glEnableVertexAttribArray(0);
        glVertexAttribPointer(0, 4, GL_FLOAT, false, 4 * Float.BYTES, 0);

        glBindBufferBase(GL_TRANSFORM_FEEDBACK_BUFFER, 0, tfTimeVbo);
        glEnable(GL_RASTERIZER_DISCARD);
        glBeginTransformFeedback(GL_POINTS);
        glDrawArrays(GL_POINTS, 0, totalTimeCases);
        glEndTransformFeedback();
        glDisable(GL_RASTERIZER_DISCARD);

        FloatBuffer outTime = BufferUtils.createFloatBuffer(totalTimeCases);
        glBindBuffer(GL_ARRAY_BUFFER, tfTimeVbo);
        glGetBufferSubData(GL_ARRAY_BUFFER, 0, outTime);

        int timeCheckIdx = 0;
        for (int m : allDivisorsM) {
            for (float l : allLookaheadsL) {
                int minTick = (int)(-l);
                int maxTick = (int)(m - l - 1);
                float prevGpuElapsed = -999.0f;
                for (int relTick = minTick; relTick <= maxTick; relTick++) {
                    float gpuElapsed = outTime.get(timeCheckIdx++);
                    assertEquals((float)relTick, gpuElapsed, 0.001f, "GPU Time Parity (M=" + m + ", L=" + l + ", relTick=" + relTick + ")");
                    if (relTick > minTick) {
                        if (gpuElapsed <= prevGpuElapsed) {
                            System.err.printf("GPU Elapsed NOT strictly monotonic at M=%d, L=%.0f: prev=%.2f, curr=%.2f%n", m, l, prevGpuElapsed, gpuElapsed);
                            System.exit(1);
                        }
                    }
                    if (gpuElapsed < -l || gpuElapsed >= (float)m - l) {
                        System.err.printf("GPU Elapsed out of bounds [-L, M-L) at M=%d, L=%.0f: val=%.2f%n", m, l, gpuElapsed);
                        System.exit(1);
                    }
                    prevGpuElapsed = gpuElapsed;
                }
            }
        }
        System.out.printf("  -> Total GPU Time Test Cases: %d verified across all M in {20..240} and L in {0, 5, 10}%n", totalTimeCases);
        System.out.println("  -> Elapsed Monotonicity & [-L, M-L) Bounds: 100% PASSED on Physical GPU\n");

        // -------------------------------------------------------------------------
        // TEST 6: SERVER QUADS INVARIANCE TEST (OLD GLSL VS NEW GLSL)
        // -------------------------------------------------------------------------
        System.out.println("Running Test 6: Server Quads Invariance (Old GLSL vs New GLSL)...");

        String serverOldVs = """
            #version 330 core
            layout (location = 0) in vec3 Position;
            layout (location = 1) in vec4 Color;
            out vec3 outPos;
            out vec4 outColor;
            void main() {
                vec3 pos = Position;
                vec4 vertexColor = Color;
                float xGui = 0;
                float yGui = 0;
                float layer = 0;
                float opacity = 1;
                int id = 1;
                switch (id) {
                    case 1: {
                        break;
                    }
                }
                vertexColor *= vec4(1, 1, 1, opacity);
                outPos = pos + vec3(xGui, yGui, layer);
                outColor = vertexColor;
            }
            """;

        String serverNewVs = """
            #version 330 core
            layout (location = 0) in vec3 Position;
            layout (location = 1) in vec4 Color;
            out vec3 outPos;
            out vec4 outColor;
            void main() {
                vec3 pos = Position;
                vec4 vertexColor = Color;
                float xGui = 0.0;
                float yGui = 0.0;
                float layer = 0.0;
                float opacity = 1.0;
                int id = 1;
                switch (id) {
                    case 0: {
                        break;
                    }
                    case 1: {
                        break;
                    }
                    default: {
                        break;
                    }
                }
                vertexColor *= vec4(1.0, 1.0, 1.0, opacity);
                outPos = pos + vec3(xGui, yGui, layer);
                outColor = vertexColor;
            }
            """;

        int progOld = compileTfProgram(serverOldVs, new CharSequence[]{"outPos", "outColor"});
        int progNew = compileTfProgram(serverNewVs, new CharSequence[]{"outPos", "outColor"});

        int serverQuadCount = 10000;
        FloatBuffer serverInBuffer = BufferUtils.createFloatBuffer(serverQuadCount * 7); // pos(3) + color(4)
        Random serverRnd = new Random(42);
        for (int i = 0; i < serverQuadCount; i++) {
            serverInBuffer.put(serverRnd.nextFloat() * 1000.0f);
            serverInBuffer.put(serverRnd.nextFloat() * 1000.0f);
            serverInBuffer.put(serverRnd.nextFloat() * 100.0f);
            serverInBuffer.put(serverRnd.nextFloat());
            serverInBuffer.put(serverRnd.nextFloat());
            serverInBuffer.put(serverRnd.nextFloat());
            serverInBuffer.put(serverRnd.nextFloat());
        }
        serverInBuffer.flip();

        int inServerVbo = glGenBuffers();
        int tfOldVbo = glGenBuffers();
        int tfNewVbo = glGenBuffers();

        glBindBuffer(GL_ARRAY_BUFFER, inServerVbo);
        glBufferData(GL_ARRAY_BUFFER, serverInBuffer, GL_STATIC_DRAW);

        glBindBuffer(GL_ARRAY_BUFFER, tfOldVbo);
        glBufferData(GL_ARRAY_BUFFER, (long)serverQuadCount * 7 * Float.BYTES, GL_DYNAMIC_READ);
        glBindBuffer(GL_ARRAY_BUFFER, tfNewVbo);
        glBufferData(GL_ARRAY_BUFFER, (long)serverQuadCount * 7 * Float.BYTES, GL_DYNAMIC_READ);

        // Run Old
        glUseProgram(progOld);
        glBindBuffer(GL_ARRAY_BUFFER, inServerVbo);
        glEnableVertexAttribArray(0);
        glVertexAttribPointer(0, 3, GL_FLOAT, false, 7 * Float.BYTES, 0);
        glEnableVertexAttribArray(1);
        glVertexAttribPointer(1, 4, GL_FLOAT, false, 7 * Float.BYTES, 3 * Float.BYTES);

        glBindBufferBase(GL_TRANSFORM_FEEDBACK_BUFFER, 0, tfOldVbo);
        glEnable(GL_RASTERIZER_DISCARD);
        glBeginTransformFeedback(GL_POINTS);
        glDrawArrays(GL_POINTS, 0, serverQuadCount);
        glEndTransformFeedback();
        glDisable(GL_RASTERIZER_DISCARD);

        // Run New
        glUseProgram(progNew);
        glBindBuffer(GL_ARRAY_BUFFER, inServerVbo);
        glEnableVertexAttribArray(0);
        glVertexAttribPointer(0, 3, GL_FLOAT, false, 7 * Float.BYTES, 0);
        glEnableVertexAttribArray(1);
        glVertexAttribPointer(1, 4, GL_FLOAT, false, 7 * Float.BYTES, 3 * Float.BYTES);

        glBindBufferBase(GL_TRANSFORM_FEEDBACK_BUFFER, 0, tfNewVbo);
        glEnable(GL_RASTERIZER_DISCARD);
        glBeginTransformFeedback(GL_POINTS);
        glDrawArrays(GL_POINTS, 0, serverQuadCount);
        glEndTransformFeedback();
        glDisable(GL_RASTERIZER_DISCARD);

        FloatBuffer outOld = BufferUtils.createFloatBuffer(serverQuadCount * 7);
        glBindBuffer(GL_ARRAY_BUFFER, tfOldVbo);
        glGetBufferSubData(GL_ARRAY_BUFFER, 0, outOld);

        FloatBuffer outNew = BufferUtils.createFloatBuffer(serverQuadCount * 7);
        glBindBuffer(GL_ARRAY_BUFFER, tfNewVbo);
        glGetBufferSubData(GL_ARRAY_BUFFER, 0, outNew);

        float maxServerPosDiff = 0.0f;
        float maxServerColDiff = 0.0f;
        for (int i = 0; i < serverQuadCount * 7; i++) {
            float vOld = outOld.get(i);
            float vNew = outNew.get(i);
            float diff = Math.abs(vOld - vNew);
            if (i % 7 < 3) {
                if (diff > maxServerPosDiff) maxServerPosDiff = diff;
            } else {
                if (diff > maxServerColDiff) maxServerColDiff = diff;
            }
        }
        assertEquals(0.0f, maxServerPosDiff, 0.000001f, "Server Quad Position Invariance");
        assertEquals(0.0f, maxServerColDiff, 0.000001f, "Server Quad Color Invariance");
        System.out.printf("  -> Verified %d server quads on physical GPU%n", serverQuadCount);
        System.out.printf("  -> Max Position Error: %.6f, Max Color Error: %.6f: 100%% INVARIANT!%n%n", maxServerPosDiff, maxServerColDiff);

        System.out.println("============================================================");
        System.out.println("  ALL HARDWARE GPU TRANSFORM FEEDBACK TESTS PASSED! (0 ERRORS)");
        System.out.println("============================================================");

        glfwDestroyWindow(window);
        glfwTerminate();
    }

    private static int compileTfProgram(String vsSource, CharSequence[] varyings) {
        int shader = glCreateShader(GL_VERTEX_SHADER);
        glShaderSource(shader, vsSource);
        glCompileShader(shader);
        if (glGetShaderi(shader, GL_COMPILE_STATUS) == GL_FALSE) {
            System.err.println("Shader compilation failed: " + glGetShaderInfoLog(shader));
            System.exit(1);
        }
        int prog = glCreateProgram();
        glAttachShader(prog, shader);
        glTransformFeedbackVaryings(prog, varyings, GL_INTERLEAVED_ATTRIBS);
        glLinkProgram(prog);
        if (glGetProgrami(prog, GL_LINK_STATUS) == GL_FALSE) {
            System.err.println("Program linking failed: " + glGetProgramInfoLog(prog));
            System.exit(1);
        }
        return prog;
    }

    private static void assertEquals(float expected, float actual, float delta, String msg) {
        if (Math.abs(expected - actual) > delta) {
            System.err.printf("ASSERTION FAILED: %s. Expected: %.3f, Actual: %.3f%n", msg, expected, actual);
            System.exit(1);
        }
    }
}
